import{_ as n,o as i,c as a,a5 as e}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"DA-1236 — Bình luận Task: triển khai và setup test","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-comments-implementation-2026-10-17.md","filePath":"feature/content-task-workflow/task-comments-implementation-2026-10-17.md"}'),h={name:"feature/content-task-workflow/task-comments-implementation-2026-10-17.md"};function o(s,t,c,r,g,l){return i(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="da-1236-—-binh-luan-task-trien-khai-va-setup-test" tabindex="-1">DA-1236 — Bình luận Task: triển khai và setup test <a class="header-anchor" href="#da-1236-—-binh-luan-task-trien-khai-va-setup-test" aria-label="Permalink to &quot;DA-1236 — Bình luận Task: triển khai và setup test&quot;">​</a></h1><p>Ngày 2026-10-17. FR 3.6.3. <a href="./3-6-3-add-comments-on-task/spec.html">Spec</a>, <a href="./3-6-3-add-comments-on-task/test.html">kết quả kiểm tra</a>.</p><h2 id="đa-trien-khai" tabindex="-1">Đã triển khai <a class="header-anchor" href="#đa-trien-khai" aria-label="Permalink to &quot;Đã triển khai&quot;">​</a></h2><ul><li>Bình luận trong hộp chi tiết Task hiện có: văn bản/link, nhắc tên thành viên, tải và xem ảnh, tải lịch sử cũ, làm mới, giữ bản nháp khi gửi lỗi. Gõ @ ngay trong ô soạn để mở dropdown nổi tại vị trí @, tự tránh mép màn hình. Chọn bằng chuột hoặc ↑↓ + Enter thành nhãn inline có highlight; xóa nhãn cuối sẽ bỏ User ID, Undo khôi phục. Esc chỉ đóng gợi ý. Email không mở gợi ý; chỉ tên được chọn mới thêm User ID mention. Nút Nhắc tên vẫn giữ. Ctrl/⌘ + Enter để gửi khi không đang chọn tên/không trong IME composition.</li><li>Manager/Creator/Client active cùng Workspace được xem/gửi trên mọi Task, kể cả manual/legacy/đã kết thúc; không phụ thuộc cờ Client duyệt hay markers lịch sử bắt đầu. Owner cần membership Manager thực tế trong Workspace.</li><li>Không sửa Task/Campaign/approval round, không mở lại công việc; không sửa/xóa comment. Nhận xét duyệt nội dung và Chat vẫn là chức năng riêng.</li><li>Thông báo in-app cho mentions + Creator phụ trách + Managers, loại tác giả và trùng; Client chỉ nhận khi được nhắc tên. Không QC, không email. Worker kiểm lại quyền trước delivery.</li><li>Mongo transaction tạo comment, gắn ảnh và ghi outbox; retry cùng tác giả/Task/clientRequestId và payload trả kết quả cũ. Thay payload cùng key trả conflict.</li></ul><h2 id="pham-vi-file-va-du-lieu" tabindex="-1">Phạm vi file và dữ liệu <a class="header-anchor" href="#pham-vi-file-va-du-lieu" aria-label="Permalink to &quot;Phạm vi file và dữ liệu&quot;">​</a></h2><p>Business: TaskCommentController, TaskCommentService/Store/Access, TaskCommentUploads/ImageValidator/UploadCleanup/Outbox, DTO và TaskCommentProperties; mở rộng TaskNotificationWorker hiện có.</p><p>Web: components/services/hooks/types trong pages/tasks, tích hợp TaskWorkflowContent và locale src/i18n/locales/{vi,en}/tasks.json. Cache đọc comment/member/image tách theo User ID; composer reset khi đổi tài khoản/Task. Không thay module viết nội dung, xuất bản, Chat, auth hoặc UI khác.</p><p>Ô soạn comment dùng Tiptap/Radix đã có trong dependencies, cấu hình riêng chỉ văn bản và mention atomic; không tái sử dụng/sửa editor Post, không thêm package. Chỉ draft có node/nhãn; khi gửi serialize về content plain text + mentions User IDs như API cũ. Chưa bổ sung vị trí/label snapshot để highlight lịch sử đã gửi. Clipboard chỉ nhận văn bản, không nhận HTML/mention ID từ ngoài.</p><p>Gateway giữ nguyên catch-all route API hiện có. Không thêm bảng PostgreSQL. Reuse user_notifications và TaskNotificationInbox hiện có.</p><p>Mongo dùng task_comments, task_comment_uploads, task_notification_outbox. <strong>File init-mongo.js và migration foundation đã có đủ schema/index cho comment</strong>, không cần migration mới cho đợt code này. Không chạy migration, init hay seed lên Atlas/demo trong đợt triển khai này. Chỉ init container kiểm thử riêng, không gắn volume dữ liệu dự án; đã dọn container/dữ liệu tạm và dừng Vite/trình duyệt kiểm thử sau khi xong.</p><h2 id="_1-kiem-tra-mongo-truoc-khi-chay-ung-dung" tabindex="-1">1. Kiểm tra Mongo trước khi chạy ứng dụng <a class="header-anchor" href="#_1-kiem-tra-mongo-truoc-khi-chay-ung-dung" aria-label="Permalink to &quot;1. Kiểm tra Mongo trước khi chạy ứng dụng&quot;">​</a></h2><p>Chạy <strong>toàn bộ</strong> playground chỉ đọc <code>docs/database/migrations/check-mongo-migrations.mongodb.js</code> trên kết nối đúng. File tự kiểm database brandhub kể cả ban đầu chọn test. Nó kiểm trạng thái schema hiện tại, không chứng minh lịch sử chạy từng file migration.</p><p>Cần ba collection cùng validator/index, đặc biệt:</p><table tabindex="0"><thead><tr><th>Collection</th><th>Index quan trọng</th></tr></thead><tbody><tr><td>task_comments</td><td>idx_task_comments_timeline; <strong>unique</strong> uq_task_comments_client_request</td></tr><tr><td>task_comment_uploads</td><td><strong>unique</strong> uq_task_comment_uploads_storage_key; idx_task_comment_uploads_owner; idx_task_comment_uploads_cleanup</td></tr><tr><td>task_notification_outbox</td><td><strong>unique</strong> uq_task_notification_outbox_event; idx_task_notification_outbox_due; idx_task_notification_outbox_lease</td></tr></tbody></table><p>Môi trường cần Mongo replica set/Atlas hỗ trợ transaction. Nếu thiếu validator/index, API gửi trả TASK_COMMENT_SCHEMA_NOT_READY; không tự tạo schema lúc ghi.</p><p>Nếu checker báo thiếu: dừng và đối chiếu schema hiện tại trước khi lập migration nâng cấp. <code>2026-10-14-task-detail-comments-foundation.js</code> là nguồn gốc ba collection này, nhưng còn chứa Task fields lịch sử đã được clean sau đó; <strong>không chạy lại toàn bộ migration cũ một cách mù quáng</strong>, không chạy init lên DB đang dùng. Không cần backfill Task chỉ để mở bình luận.</p><h2 id="_2-kiem-tra-storage-va-postgresql" tabindex="-1">2. Kiểm tra storage và PostgreSQL <a class="header-anchor" href="#_2-kiem-tra-storage-va-postgresql" aria-label="Permalink to &quot;2. Kiểm tra storage và PostgreSQL&quot;">​</a></h2><ul><li>Dùng cấu hình FileStorageService/S3 hiện có, không in hoặc gửi credentials. Service cần quyền PutObject/GetObject/DeleteObject trên prefix <code>task-comment-images/</code>.</li><li>Prefix này <strong>phải private</strong>, không nằm trong public policy/prefix <code>image/</code>. API không trả S3 URL/key; ảnh tải qua API có auth, kiểm quyền Task, no-store/nosniff. Chưa kiểm chứng bucket policy thật trong đợt này; phải review policy trước khi dùng ảnh nhạy cảm.</li><li>DRAFT chỉ chủ upload preview được và chỉ khi chưa hết hạn; ATTACHED theo quyền Workspace/Task hiện tại. Không dùng endpoint Mail hoặc Material Library.</li><li>PostgreSQL cần user_notifications hiện có. Notification worker lấy outbox Mongo, ghi inbox SQL bằng ID ổn định + ON CONFLICT; chỉ SENT sau commit, lỗi thì retry. Không có migration PostgreSQL mới.</li></ul><h2 id="_3-cau-hinh-ky-thuat" tabindex="-1">3. Cấu hình kỹ thuật <a class="header-anchor" href="#_3-cau-hinh-ky-thuat" aria-label="Permalink to &quot;3. Cấu hình kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Mặc định</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td>app.task-comments.draft-hours</td><td>24</td><td>Thời gian giữ ảnh nháp chưa gắn comment</td></tr><tr><td>app.task-comments.max-draft-uploads-per-user</td><td>20</td><td>Trần ảnh DRAFT theo User <strong>trong từng Task</strong>; không phải số ảnh mỗi comment</td></tr><tr><td>app.task-comments.cleanup-enabled</td><td>true</td><td>Bật worker dọn ảnh nháp hết hạn</td></tr><tr><td>app.task-comments.cleanup-ms</td><td>60000</td><td>Chu kỳ dọn, batch tối đa 20; lease 300 giây</td></tr><tr><td>app.task-notifications.enabled</td><td>true</td><td>Worker thông báo Task/comment hiện có</td></tr><tr><td>app.task-notifications.poll-ms</td><td>5000</td><td>Chu kỳ lấy sự kiện thông báo</td></tr></tbody></table><p>Comment bắt buộc văn bản không rỗng, tối đa 10.000 ký tự. Tối đa 100 User ID mention đang hoạt động, tra cứu theo trang 50. Tối đa 5 ảnh/comment, JPEG/PNG/WebP, mỗi ảnh tối đa 5 MiB (5.242.880 byte); MIME/decode thật và trần 20 triệu điểm ảnh chống quá tải decode.</p><p>spring.servlet.multipart.max-file-size giữ 5MB; max-request-size tăng từ 5MB lên <strong>6MB</strong> để đủ overhead multipart cho <strong>một ảnh 5MB</strong>. UI tải từng file tuần tự, không gửi năm ảnh trong cùng request. Reverse proxy (nếu có) cần cho request tương ứng.</p><p>Cleanup dùng lease/CAS DRAFT → CLEANUP_PENDING; chỉ xóa metadata sau khi xóa object thành công, không TTL metadata và không dọn ảnh ATTACHED. Ảnh người dùng bỏ khỏi bản nháp sẽ hết hạn rồi được dọn, không xóa ngay ảnh có thể vừa được gắn.</p><h2 id="_4-chay-va-test-thu-cong" tabindex="-1">4. Chạy và test thủ công <a class="header-anchor" href="#_4-chay-va-test-thu-cong" aria-label="Permalink to &quot;4. Chạy và test thủ công&quot;">​</a></h2><ol><li><p>Kiểm Mongo/schema, cấu hình S3 private và PostgreSQL như trên. Không cần reset DB/seed thêm tài khoản.</p></li><li><p>Business: dừng process cũ, clean compile và chạy lại từ đúng thư mục <code>brandhub-business-service</code>:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mvn.cmd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> compile</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mvn.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spring</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">boot:run</span></span></code></pre></div><p>Trong cmd khi đổi ổ đĩa dùng <code>cd /d D:\\FPT\\FA26\\SEP490\\brandhub-business-service</code>. Đã gặp class cũ/IDE ghi lại target/classes trong quá trình kiểm tra; clean build/restart trước khi kết luận API chưa có. Không thay cấu hình IDE của thành viên.</p></li><li><p>Chạy Gateway và Web theo cấu hình hiện có. Mở Danh sách công việc → một Task → phần <strong>Bình luận công việc</strong> bên dưới chi tiết.</p></li><li><p>Manager gửi văn bản + link, nhắc Creator/Client; đổi sang các tài khoản test có sẵn của cùng Workspace và kiểm timeline/thông báo/link mở đúng Task. Không nhắc Client thì Client không nhận notification tự động.</p></li><li><p>Thử ảnh hợp lệ và ảnh quá 5MB/sai định dạng, xem preview trước/sau gửi. Client khác không xem được DRAFT của người gửi; ATTACHED cùng Task thì xem được.</p></li><li><p>Ngắt mạng lúc gửi, kiểm nội dung giữ lại rồi <strong>Thử gửi lại</strong>; cùng nội dung không xuất hiện hai lần. Bản nháp chưa gửi phải được xác nhận trước khi đóng bằng dialog ứng dụng.</p></li><li><p>Thử Task FINISHED/CANCELLED và Task manual, Client vẫn xem/gửi; status Task/Campaign không đổi. Thử tài khoản ngoài/bị gỡ Workspace phải bị chặn. Kiểm cả light/dark, vi/en và màn hình nhỏ.</p></li></ol><p>Timeline không tự đồng bộ qua WebSocket trong đợt này; người khác bấm <strong>Làm mới</strong> để lấy bình luận mới.</p><h2 id="_5-ket-qua-va-gioi-han-ban-giao" tabindex="-1">5. Kết quả và giới hạn bàn giao <a class="header-anchor" href="#_5-ket-qua-va-gioi-han-ban-giao" aria-label="Permalink to &quot;5. Kết quả và giới hạn bàn giao&quot;">​</a></h2><p>Đã qua 46 test Task hiện có, 38 assertions smoke trên Mongo replica set cô lập (mock S3/SQL repos/inbox), lint Web mới và browser API-mock cho mention/retry/ảnh/layout. Không thêm/commit file test dưới src. Không chạm dữ liệu Atlas/demo, không seed tài khoản.</p><p>Chưa xác minh S3 policy/IAM thật, notification inbox SQL thật, request multipart qua Gateway thật, crash sau SQL commit và các race cross-store trên môi trường dùng chung. Typecheck toàn Web còn lỗi ngoài scope ở Content Writing/editor/Workspace dashboard/AppRoutes; chưa sửa phần thành viên khác. Chờ team review và kiểm thử tích hợp trước khi đánh Done Jira/Report.</p>`,29)])])}const k=n(h,[["render",o]]);export{d as __pageData,k as default};
